 'view',pg_get_viewdef('public.phone_recording_pipeline_state'::regclass),
 'indexes',(select jsonb_agg(to_jsonb(x) order by x.indexname) from pg_indexes x where x.schemaname='public' and x.tablename in ('learn_email_source_versions','email_messages')),
 'policies',(select jsonb_agg(to_jsonb(x) order by x.tablename,x.policyname) from pg_policies x where x.schemaname='public' and x.tablename in ('learn_email_source_versions','email_messages'))
 ) as catalog)))::text) as fingerprint,(select digest from (select jsonb_build_object('owner',proowner,'acl',proacl,'securityDefiner',prosecdef,'config',proconfig) as permissions,md5(pg_get_functiondef(oid)) as digest from pg_proc where oid='public.learn_operator_capture_health(uuid,text)'::regprocedure)m) as digest;
commit;
